package vn.edu.tdtu.fitcenter.renewal;
import org.springframework.beans.factory.annotation.Value;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.TransactionDefinition;import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.ObjectMapper;import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;
@Service
public class RenewalService {
 private final JdbcTemplate jdbc;private final ObjectMapper json;private final Clock clock;private final boolean enabled;private final MembershipPeriodService periods;private final TransactionTemplate tx,read;
 public record Result(int status,Map<String,Object> body,boolean replayed){}
 private record Decision(Result result,String error){}
 public RenewalService(JdbcTemplate jdbc,ObjectMapper json,Clock clock,PlatformTransactionManager manager,MembershipPeriodService periods,@Value("${fitcenter.renewal.enabled:false}")boolean enabled){this.jdbc=jdbc;this.json=json;this.clock=clock;this.periods=periods;this.enabled=enabled;tx=new TransactionTemplate(manager);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);tx.setTimeout(10);read=new TransactionTemplate(manager);read.setReadOnly(true);read.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);read.setTimeout(10);}
 private void gate(){if(!enabled)throw new RenewalFailure(503,"ERR_RENEWAL_UNAVAILABLE","Renewal simulator is unavailable in this environment");}
 private UUID actor(String email,String role){var rows=jdbc.queryForList("SELECT id FROM users WHERE lower(email)=lower(?) AND role=? AND status='ACTIVE'",email,role);if(rows.size()!=1)throw new AccessDeniedException("ACTIVE account with required role needed");return (UUID)rows.getFirst().get("id");}
 private UUID member(String email){UUID user=actor(email,"MEMBER");var rows=jdbc.queryForList("SELECT id FROM members WHERE user_id=?",user);if(rows.isEmpty())throw missing();return (UUID)rows.getFirst().get("id");}
 private static RenewalFailure missing(){return new RenewalFailure(404,"ERR_NOT_FOUND","Resource not found");}
 private void lockMember(UUID member){if(jdbc.queryForList("SELECT id FROM members WHERE id=? FOR NO KEY UPDATE",member).isEmpty())throw missing();}
 private Map<String,Object> lockMembership(UUID member,UUID membership){var rows=jdbc.queryForList("SELECT id,plan_id,status,start_date,expiry_date FROM memberships WHERE id=? AND member_id=? FOR UPDATE",membership,member);if(rows.isEmpty())throw missing();return rows.getFirst();}
 private static String fingerprint(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception ex){throw new IllegalStateException(ex);}}
 private static LocalDate date(Object value){return value==null?null:((java.sql.Date)value).toLocalDate();}
 private Map<String,Object> raw(UUID id){var rows=jdbc.queryForList("SELECT q.*,p.provider_ref,p.provider actual_provider,p.plan_id actual_plan_id,p.amount actual_amount,p.status payment_status,p.processed_at,p.period_start,p.period_end FROM renewal_payment_quotes q JOIN payment_transactions p ON p.id=q.payment_id WHERE q.payment_id=?",id);if(rows.isEmpty())throw missing();return rows.getFirst();}
 private Map<String,Object> dto(Map<String,Object> r){var out=new LinkedHashMap<String,Object>();out.put("id",r.get("payment_id"));out.put("requestId",r.get("idempotency_key"));out.put("membershipId",r.get("membership_id"));out.put("memberId",r.get("member_id"));out.put("planId",r.get("plan_id"));out.put("planName",r.get("plan_name_snapshot"));out.put("amount",((BigDecimal)r.get("amount_snapshot")).toPlainString());out.put("durationDays",r.get("duration_days_snapshot"));out.put("currency",r.get("currency"));out.put("provider","SIMULATOR");out.put("providerRef",r.get("provider_ref"));out.put("status",r.get("payment_status"));out.put("fulfillmentStatus",r.get("fulfillment_status"));out.put("reconciliationReason",r.get("reconciliation_reason"));out.put("periodId",r.get("applied_period_id"));out.put("periodStart",date(r.get("period_start"))==null?null:date(r.get("period_start")).toString());out.put("periodEnd",date(r.get("period_end"))==null?null:date(r.get("period_end")).toString());out.put("createdAt",((java.sql.Timestamp)r.get("created_at")).toInstant().toString());out.put("processedAt",r.get("processed_at")==null?null:((java.sql.Timestamp)r.get("processed_at")).toInstant().toString());return out;}
 private Result replay(UUID key,UUID member,String hash){var rows=jdbc.queryForList("SELECT payment_id,member_id,request_fingerprint FROM renewal_payment_quotes WHERE idempotency_key=?",key);if(rows.isEmpty())return null;var r=rows.getFirst();if(!member.equals(r.get("member_id"))||!hash.equals(r.get("request_fingerprint")))throw RenewalFailure.conflict("ERR_IDEMPOTENCY_KEY_REUSED","Key belongs to another request");return new Result(200,dto(raw((UUID)r.get("payment_id"))),true);}
 public Result initiate(String email,UUID membership,UUID key,RenewalRequests.Create request){gate();UUID owner=member(email);String hash=fingerprint("M05-v1|"+owner+"|"+membership+"|"+request.planId());
  try{return tx.execute(s->{lockMember(owner);Result old=replay(key,owner,hash);if(old!=null){actor(email,"MEMBER");return old;}var m=lockMembership(owner,membership);
   if(!Set.of("ACTIVE","EXPIRED").contains(m.get("status")))throw RenewalFailure.conflict("ERR_MEMBERSHIP_NOT_RENEWABLE","Membership is not eligible for renewal");
   LocalDate last=jdbc.queryForObject("SELECT max(end_date) FROM membership_paid_periods WHERE membership_id=?",LocalDate.class,membership);if(last==null)throw RenewalFailure.conflict("ERR_MEMBERSHIP_COVERAGE_UNKNOWN","No verified paid coverage; reconcile first");
   var plans=jdbc.queryForList("SELECT id,name,price,duration_days,status FROM membership_plans WHERE id=? FOR SHARE",request.planId());if(plans.isEmpty())throw missing();var p=plans.getFirst();if(!"ACTIVE".equals(p.get("status")))throw RenewalFailure.conflict("ERR_PLAN_NO_LONGER_AVAILABLE","Plan is not ACTIVE");actor(email,"MEMBER");Instant now=clock.instant();int days=((Number)p.get("duration_days")).intValue();RenewalDates.next(now,last,days);UUID id=UUID.randomUUID();
   jdbc.update("INSERT INTO payment_transactions(id,member_id,plan_id,membership_id,provider,provider_ref,amount,status) VALUES(?,?,?,?,'SIMULATOR',?,?,'PENDING')",id,owner,request.planId(),membership,"sim:"+id,p.get("price"));
   jdbc.update("INSERT INTO renewal_payment_quotes(payment_id,member_id,membership_id,plan_id,idempotency_key,request_fingerprint,plan_name_snapshot,amount_snapshot,duration_days_snapshot,currency,created_at) VALUES(?,?,?,?,?,?,?,?,?,'VND',?)",id,owner,membership,request.planId(),key,hash,p.get("name"),p.get("price"),days,OffsetDateTime.ofInstant(now,ZoneOffset.UTC));return new Result(201,dto(raw(id)),false);
  });}catch(DataIntegrityViolationException ex){return tx.execute(s->{actor(email,"MEMBER");Result old=replay(key,owner,hash);if(old!=null)return old;throw RenewalFailure.conflict("ERR_RENEWAL_CONFLICT","Concurrent data conflict; reconcile before retry");});}
 }
 public List<Map<String,Object>> mine(String email){gate();return read.execute(s->{UUID owner=member(email);return jdbc.queryForList("SELECT payment_id FROM renewal_payment_quotes WHERE member_id=? ORDER BY created_at DESC,payment_id",UUID.class,owner).stream().map(id->dto(raw(id))).toList();});}
 public Map<String,Object> payment(String email,UUID id){gate();return read.execute(s->{UUID owner=member(email);var r=raw(id);if(!owner.equals(r.get("member_id")))throw missing();return dto(r);});}
 public Map<String,Object> history(String email,UUID membership){gate();return read.execute(s->{UUID owner=member(email);if(jdbc.queryForList("SELECT id FROM memberships WHERE id=? AND member_id=?",membership,owner).isEmpty())throw missing();Instant checked=clock.instant();return Map.of("membershipId",membership,"checkedAt",checked.toString(),"periods",periods.dto(membership,LocalDate.ofInstant(checked,ZoneId.of("Asia/Ho_Chi_Minh"))));});}
 public List<Map<String,Object>> adminList(String email){gate();return read.execute(s->{actor(email,"ADMIN");return jdbc.queryForList("SELECT payment_id FROM renewal_payment_quotes ORDER BY created_at DESC,payment_id",UUID.class).stream().map(id->dto(raw(id))).toList();});}
 public List<Map<String,Object>> events(String email,UUID id){gate();return read.execute(s->{actor(email,"ADMIN");raw(id);return jdbc.queryForList("SELECT id,event_key,reported_status,outcome,error_code,http_status,actor_user_id,checked_at FROM renewal_payment_events WHERE payment_id=? ORDER BY checked_at,id",id).stream().map(r->{var out=new LinkedHashMap<String,Object>();out.put("id",r.get("id"));out.put("eventId",r.get("event_key"));out.put("reportedStatus",r.get("reported_status"));out.put("outcome",r.get("outcome"));out.put("errorCode",r.get("error_code"));out.put("httpStatus",r.get("http_status"));out.put("actorUserId",r.get("actor_user_id"));out.put("checkedAt",((java.sql.Timestamp)r.get("checked_at")).toInstant().toString());return (Map<String,Object>)out;}).toList();});}
 public Result settle(String email,UUID id,RenewalRequests.Event event){gate();String hash=fingerprint("M06-v1|"+id+"|"+event.providerRef()+"|"+event.amount().setScale(2).toPlainString()+"|"+event.currency()+"|"+event.status());
  Decision decision=tx.execute(s->{UUID admin=actor(email,"ADMIN");var link=raw(id);UUID owner=(UUID)link.get("member_id"),membership=(UUID)link.get("membership_id");lockMember(owner);var m=lockMembership(owner,membership);
   jdbc.queryForList("SELECT p.id FROM payment_transactions p JOIN renewal_payment_quotes q ON q.payment_id=p.id WHERE p.id=? FOR UPDATE OF p,q",id);actor(email,"ADMIN");
   // Event claim is always after Member -> Membership -> payment/quote. No path locks event then Member.
   jdbc.update("INSERT INTO renewal_result_keys(event_key,payment_id,first_fingerprint,created_at) VALUES(?,?,?,?) ON CONFLICT(event_key) DO NOTHING",event.eventId(),id,hash,OffsetDateTime.ofInstant(clock.instant(),ZoneOffset.UTC));
   var claim=jdbc.queryForMap("SELECT first_fingerprint FROM renewal_result_keys WHERE event_key=? FOR UPDATE",event.eventId());actor(email,"ADMIN");Instant now=clock.instant();
   var previous=jdbc.queryForList("SELECT response_snapshot::text snapshot,http_status,error_code FROM renewal_payment_events WHERE event_key=? AND request_fingerprint=?",event.eventId(),hash);
   if(!previous.isEmpty()){var p=previous.getFirst();@SuppressWarnings("unchecked") Map<String,Object> body=json.readValue((String)p.get("snapshot"),Map.class);return new Decision(new Result(((Number)p.get("http_status")).intValue(),body,true),(String)p.get("error_code"));}
   var current=raw(id);String error=null,outcome="ALREADY_PROCESSED";String state=(String)current.get("payment_status"),fulfillment=(String)current.get("fulfillment_status");boolean changed=false;
   if(!hash.equals(claim.get("first_fingerprint"))){error="ERR_PAYMENT_EVENT_KEY_REUSED";outcome="EVENT_KEY_CONFLICT";}
   else if(!"SIMULATOR".equals(current.get("actual_provider"))||!current.get("plan_id").equals(current.get("actual_plan_id"))||((BigDecimal)current.get("actual_amount")).compareTo((BigDecimal)current.get("amount_snapshot"))!=0||!event.providerRef().equals(current.get("provider_ref"))||event.amount().compareTo((BigDecimal)current.get("amount_snapshot"))!=0||!event.currency().equals(current.get("currency"))){error="ERR_PAYMENT_RESULT_MISMATCH";outcome="REJECTED_MISMATCH";}
   else if(state.equals("SUCCESS")){
    if(!event.status().equals("SUCCESS")){error="ERR_PAYMENT_RESULT_CONFLICT";outcome="TERMINAL_CONFLICT";}
   }else if(event.status().equals("SUCCESS")){
    jdbc.update("UPDATE payment_transactions SET status='SUCCESS',processed_at=? WHERE id=?",OffsetDateTime.ofInstant(now,ZoneOffset.UTC),id);changed=true;
    String reason=!state.equals("PENDING")?"LATE_SUCCESS_AFTER_TERMINAL":!Set.of("ACTIVE","EXPIRED").contains(m.get("status"))?"MEMBERSHIP_STATE_CHANGED":null;
    RenewalDates.Period period=null;if(reason==null){LocalDate last=jdbc.queryForObject("SELECT max(end_date) FROM membership_paid_periods WHERE membership_id=?",LocalDate.class,membership);try{period=RenewalDates.next(now,last,((Number)current.get("duration_days_snapshot")).intValue());}catch(RenewalFailure ex){reason="PERIOD_DATE_RANGE";}}
    if(reason!=null){jdbc.update("UPDATE renewal_payment_quotes SET fulfillment_status='RECONCILIATION_REQUIRED',reconciliation_reason=? WHERE payment_id=?",reason,id);outcome="RECONCILIATION_REQUIRED";}
    else{UUID periodId=UUID.randomUUID();jdbc.update("INSERT INTO membership_paid_periods(id,member_id,membership_id,plan_id,plan_name_snapshot,source,start_date,end_date,amount_snapshot,duration_days_snapshot,currency,payment_transaction_id) VALUES(?,?,?,?,?,'RENEWAL',?,?,?,?,'VND',?)",periodId,owner,membership,current.get("plan_id"),current.get("plan_name_snapshot"),period.start(),period.end(),current.get("amount_snapshot"),current.get("duration_days_snapshot"),id);
     LocalDate today=LocalDate.ofInstant(now,ZoneId.of("Asia/Ho_Chi_Minh"));LocalDate start=date(m.get("expiry_date")).isBefore(today)?period.start():date(m.get("start_date"));
     jdbc.update("UPDATE memberships SET start_date=?,expiry_date=?,status='ACTIVE' WHERE id=?",start,period.end(),membership);
     jdbc.update("UPDATE payment_transactions SET period_start=?,period_end=? WHERE id=?",period.start(),period.end(),id);
     jdbc.update("UPDATE renewal_payment_quotes SET fulfillment_status='APPLIED',applied_period_id=? WHERE payment_id=?",periodId,id);outcome="APPLIED";
    }
   }else if(state.equals("PENDING")){jdbc.update("UPDATE payment_transactions SET status=?,processed_at=? WHERE id=?",event.status(),OffsetDateTime.ofInstant(now,ZoneOffset.UTC),id);outcome=event.status();changed=true;}
   else if(!state.equals(event.status())){error="ERR_PAYMENT_RESULT_CONFLICT";outcome="TERMINAL_CONFLICT";}
   var response=dto(raw(id));response.put("eventId",event.eventId());response.put("eventOutcome",outcome);
   jdbc.update("INSERT INTO renewal_payment_events(event_key,payment_id,request_fingerprint,reported_status,supplied_provider_ref,supplied_amount,supplied_currency,outcome,error_code,http_status,actor_user_id,checked_at,response_snapshot) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?::jsonb)",event.eventId(),id,hash,event.status(),event.providerRef(),event.amount(),event.currency(),outcome,error,error==null?200:409,admin,OffsetDateTime.ofInstant(now,ZoneOffset.UTC),json.writeValueAsString(response));
   if(changed)jdbc.update("INSERT INTO audit_logs(actor_user_id,actor_type,action,entity_type,entity_id,details,created_at) VALUES(?,'USER',?,'PAYMENT',?,jsonb_build_object('eventId',?::text,'outcome',?::text),?)",admin,"SIMULATOR_PAYMENT_"+event.status(),id,event.eventId().toString(),outcome,OffsetDateTime.ofInstant(now,ZoneOffset.UTC));
   return new Decision(new Result(error==null?200:409,response,false),error);
  });
  // Expected mismatch/conflict traces commit; throw only outside the transaction.
  if(decision.error()!=null)throw RenewalFailure.conflict(decision.error(),"Payment result conflicts with its reference, snapshot or prior result; reconcile the recorded event");return decision.result();
 }
}
